package com.alsafa.native4;import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.widget.TextView;import android.widget.Button;import android.widget.LinearLayout;import android.view.ViewGroup;import com.alsafa.native4.core.*;import java.text.SimpleDateFormat;import java.util.*;
public final class SimpleHomeActivity extends Activity{private CoreDb db;private Native4Services services;@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_simple_home);db=new CoreDb(this);services=new Native4Services(db,"native4-android-alpha");findViewById(R.id.pageBack).setOnClickListener(v->finish());findViewById(R.id.openFull).setOnClickListener(v->startActivity(new Intent(this,AdvancedHomeActivity.class)));findViewById(R.id.openSale).setOnClickListener(v->startActivity(new Intent(this,SaleActivity.class)));findViewById(R.id.openRepair).setOnClickListener(v->startActivity(new Intent(this,DirectPartSaleActivity.class)));findViewById(R.id.openShift).setOnClickListener(v->startActivity(new Intent(this,ClosingActivity.class)));findViewById(R.id.openHandover).setOnClickListener(v->startActivity(new Intent(this,HandoverActivity.class)));findViewById(R.id.simpleSync).setOnClickListener(v->startActivity(new Intent(this,SyncCenterActivity.class)));renderQuickRepairs();refresh();}
@Override protected void onResume(){super.onResume();if(services!=null){renderQuickRepairs();refresh();Native4AutoSync.request(this,db,this::refresh);}}
private void renderQuickRepairs(){LinearLayout box=findViewById(R.id.simpleQuickRepairs);box.removeAllViews();java.util.List<QuickRepairButtonStore.Item> items=services.quickRepairButtons.active();if(items.isEmpty()){TextView t=new TextView(this);t.setText("لا توجد أزرار مرتبطة بعد — افتح الصيانة السريعة ثم إدارة الأزرار.");t.setPadding(8,8,8,8);box.addView(t);return;}LinearLayout row=null;for(int i=0;i<items.size();i++){if(i%2==0){row=new LinearLayout(this);row.setOrientation(LinearLayout.HORIZONTAL);box.addView(row);}QuickRepairButtonStore.Item x=items.get(i);Button b=new Button(this);b.setAllCaps(false);b.setMinHeight(86);b.setText(x.icon+" "+x.label+"\n"+x.partName+" — متاح "+x.quantity);b.setBackgroundResource(R.drawable.alsafa_card);b.setOnClickListener(v->{Intent in=new Intent(this,DirectPartSaleActivity.class);in.putExtra("quick_part_id",x.partId);startActivity(in);});row.addView(b,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));}}
private void refresh(){((TextView)findViewById(R.id.simpleSync)).setText(Native4AutoSync.status());try{DeveloperTodaySummaryStore.Summary s=services.developerToday.read(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));((TextView)findViewById(R.id.simpleMoney)).setText("المدوّر من الإقفال السابق\n"+money(s.carry)+"\n\nمبيعات اليوم\n"+money(s.sales)+"\n\nصيانة اليوم\n"+money(s.repairs));}catch(Exception e){((TextView)findViewById(R.id.simpleMoney)).setText("تعذر قراءة ملخص اليوم: "+msg(e));}}
private static String money(DeveloperTodaySummaryStore.Money m){return String.format(Locale.US,"USD %.2f   |   TRY %.2f   |   SYP %.2f",m.usd,m.tryAmount,m.syp);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}}
